package com.aoo.bcg.roomsafety;
import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import java.sql.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class JdbcRoomSafetyServiceTest{private JdbcDataSource db;private JdbcRoomSafetyService service;
@BeforeEach void setUp()throws Exception{db=new JdbcDataSource();db.setURL("jdbc:h2:mem:safety;MODE=MySQL;DB_CLOSE_DELAY=-1");try(Connection c=db.getConnection();Statement s=c.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE aoo_hall_room(room_id BIGINT PRIMARY KEY,owner_account_id BIGINT,state VARCHAR(16))");s.execute("CREATE TABLE aoo_hall_room_member(room_id BIGINT,account_id BIGINT,status VARCHAR(16),PRIMARY KEY(room_id,account_id))");s.execute("CREATE TABLE room_safety_report(report_id VARCHAR(36) PRIMARY KEY,room_id BIGINT,reporter_id BIGINT,target_player_id BIGINT,category VARCHAR(24),detail VARCHAR(1000),status VARCHAR(20),idempotency_key VARCHAR(128),created_at TIMESTAMP,UNIQUE(reporter_id,idempotency_key))");s.execute("CREATE TABLE room_safety_mute(room_id BIGINT,player_id BIGINT,muted_by BIGINT,reason VARCHAR(256),muted_until TIMESTAMP,idempotency_key VARCHAR(128),created_at TIMESTAMP,PRIMARY KEY(room_id,player_id),UNIQUE(muted_by,idempotency_key))");s.execute("CREATE TABLE room_safety_location(room_id BIGINT,player_id BIGINT,latitude DOUBLE,longitude DOUBLE,accuracy_meters DOUBLE,observed_at TIMESTAMP,PRIMARY KEY(room_id,player_id))");s.execute("INSERT INTO aoo_hall_room VALUES(7,10,'PLAYING')");s.execute("INSERT INTO aoo_hall_room_member VALUES(7,10,'JOINED'),(7,11,'JOINED'),(7,12,'LEFT')");}service=new JdbcRoomSafetyService(db,Clock.fixed(Instant.parse("2026-08-24T00:00:00Z"),ZoneOffset.UTC));}
@Test void reportIsIdempotentAndRequiresAuthorityMembership(){var a=service.report(10,7L,11L,"ABUSE","spam","same");var b=service.report(10,7L,11L,"ABUSE","spam","same");assertEquals(a.get("reportId"),b.get("reportId"));assertEquals("ROOM_MEMBERSHIP_REQUIRED",assertThrows(RoomSafetyException.class,()->service.report(12,7L,11L,"ABUSE","spam","x")).code);}
@Test void ownerCanMuteButPlayerCannot(){assertTrue(service.mute(10,7,11,10,"spam","m1").containsKey("mutedUntil"));assertEquals(true,service.muteStatus(11,7).get("muted"));assertEquals("ROOM_SAFETY_FORBIDDEN",assertThrows(RoomSafetyException.class,()->service.mute(11,7,10,10,"x","m2")).code);}
@Test void computesDistanceOnlyForJoinedAuthoritativeMembers(){service.location(10,7,31.2304,121.4737,8);var state=service.location(11,7,31.2305,121.4738,8);assertEquals(1,((java.util.List<?>)state.get("pairs")).size());assertEquals(true,((java.util.Map<?,?>)((java.util.List<?>)state.get("pairs")).getFirst()).get("authoritative"));}}
